import {occasions} from './occasions.js';
export const signaturePatterns=['Carinho de capivara','Cartinhas e laços','Festa de lembranças','Jardim de afetos'];
export const patterns={natal:['Noite de Natal','Laços de carinho','Xadrez rubi','Bosque de papel'],aniversario:['Confete delicado','Céu de desejos','Fitas de festa','Bandeirinhas'],casamento:['Ramos em azul','Arcos rubi','Linho natural','Jardim em azul'],maes:['Floral em azul','Arcos de carinho','Papel natural','Jardim delicado'],pais:['Folhas ao vento','Xadrez em azul','Constelações','Traços em azul'],namorados:['Corações em traço','Laços rubi','Cartas de amor','Listras framboesa'],pascoa:['Ovos pintados','Margaridas','Ramos e doçura','Xadrez caramelo'],amizade:['Sol de cada dia','Flores de amizade','Cartinhas','Arcos caramelo']};
export const patternLabels={natal:'Natal',aniversario:'Aniversário',casamento:'Casamento',maes:'Dia das Mães',pais:'Dia dos Pais',namorados:'Namorados',pascoa:'Páscoa',amizade:'Só porque sim'};
export const themeGroup=occasion=>occasions[occasion]?.material||'amizade';
export const materials={algodao:'Papel de algodão',linho:'Linho',kraft:'Kraft natural'};
export function createMaterials(getState,onChange){
 const panel=document.createElement('details');panel.className='options-panel materials-panel';panel.innerHTML='<summary>Material e estampas do tema</summary><div class="material-options"></div><p class="options-label">Escolha a estampa</p><div class="pattern-options"></div><button class="generate-variations" type="button">Gerar variações deste tema ↻</button><div class="variation-results" aria-live="polite"></div>';
 document.querySelector('.customizer-bottom').before(panel);
 const gallery=document.createElement('section');gallery.className='finish-gallery section-width';gallery.innerHTML='<div class="section-heading"><div><h2>O tema continua<br>em cada detalhe.</h2></div><p>Estampas da nossa capivara.<br>Uma coleção de carinho para cada ocasião.</p></div><div class="finish-grid"></div>';
 const picker=document.createElement('div');picker.className='finish-picker';const pickerLabel=document.createElement('label');pickerLabel.htmlFor='finish-occasion';pickerLabel.textContent='Ver estampas para';const finishSelect=document.createElement('select');finishSelect.id='finish-occasion';for(const [key,label] of Object.entries(patternLabels))finishSelect.add(new Option(label,key));picker.append(pickerLabel,finishSelect);gallery.querySelector('.finish-grid').before(picker);
 for(const [key,names] of Object.entries(patterns)){const group=document.createElement('article');group.className='finish-group';group.dataset.finishTheme=key;const title=document.createElement('h3');title.textContent=patternLabels[key];const tiles=document.createElement('div');tiles.className='finish-tiles';names.forEach((name,i)=>{const button=document.createElement('button'),img=document.createElement('img'),label=document.createElement('span');img.src='assets/pattern-'+key+'-'+i+'.webp';img.alt='Estampa '+name;img.loading='lazy';img.width=512;img.height=512;label.textContent=name;button.append(img,label);button.addEventListener('click',()=>{onChange({occasion:key,pattern:key+'-'+i});document.getElementById('atelier').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});panel.open=true;document.dispatchEvent(new CustomEvent('creator:reveal',{detail:'.materials-panel'}));});tiles.append(button);});group.append(title,tiles);gallery.querySelector('.finish-grid').append(group);}document.querySelector('.faq-section').before(gallery);
 function showFinishes(theme){finishSelect.value=theme;gallery.querySelectorAll('[data-finish-theme]').forEach(element=>element.hidden=element.dataset.finishTheme!==theme);}
 finishSelect.addEventListener('change',()=>showFinishes(finishSelect.value));

 for(const [id,label] of Object.entries(materials)){const b=document.createElement('button');b.dataset.material=id;b.className='material-choice';b.innerHTML='<span aria-hidden="true"></span>';b.firstChild.style.backgroundImage='url(assets/material-'+id+'.webp)';b.append(document.createTextNode(label));b.addEventListener('click',()=>onChange({texture:id}));panel.querySelector('.material-options').append(b);}
 const signature=document.createElement('div');signature.className='signature-patterns';const signatureTitle=document.createElement('p');signatureTitle.className='options-label';signatureTitle.textContent='Coleção Capimimo · novas estampas';signature.append(signatureTitle);const signatureGrid=document.createElement('div');signatureGrid.className='pattern-options';signaturePatterns.forEach((label,index)=>{const button=document.createElement('button');button.type='button';button.dataset.pattern='signature-'+index;const image=document.createElement('img'),name=document.createElement('span');image.src='assets/pattern-signature-'+index+'.webp';image.alt='';name.textContent=label;button.append(image,name);button.addEventListener('click',()=>onChange({pattern:'signature-'+index}));signatureGrid.append(button);});signature.append(signatureGrid);panel.querySelector('.material-options').after(signature);
 const signatureGallery=document.createElement('article');signatureGallery.className='signature-finish-group';signatureGallery.innerHTML='<h3>Carinho em cada detalhe</h3><p>Quatro estampas da nossa capivara, para combinar com as suas fotos.</p>';const signatureTiles=signatureGrid.cloneNode(true);signatureTiles.querySelectorAll('button').forEach((button,index)=>{button.querySelector('img').loading='lazy';button.addEventListener('click',()=>{onChange({pattern:'signature-'+index});document.dispatchEvent(new CustomEvent('creator:reveal',{detail:'.materials-panel'}));panel.open=true;document.querySelector('#atelier').scrollIntoView({behavior:'instant'});});});signatureGallery.append(signatureTiles);gallery.querySelector('.finish-grid').prepend(signatureGallery);
 let group='',round=0;
 function render(){const s=getState(),next=themeGroup(s.occasion);showFinishes(next);if(next!==group){group=next;const options=panel.querySelector('.pattern-options');options.replaceChildren();patterns[group].forEach((label,i)=>{const b=document.createElement('button');b.dataset.pattern=group+'-'+i;b.innerHTML='<img alt=""><span></span>';b.querySelector('img').src='assets/pattern-'+group+'-'+i+'.webp';b.querySelector('span').textContent=label;b.addEventListener('click',()=>onChange({pattern:b.dataset.pattern}));options.append(b);});panel.querySelector('.variation-results').replaceChildren();}panel.querySelectorAll('[data-material]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.material===s.texture)));panel.querySelectorAll('[data-pattern]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.pattern===s.pattern)));}
 panel.querySelector('.generate-variations').addEventListener('click',()=>{round++;const results=panel.querySelector('.variation-results');results.replaceChildren();const colors=['#B94162','#4A7294','#835A38','#5B486D'];for(let i=0;i<3;i++){const n=(round+i)%4,texture=Object.keys(materials)[(round+i)%3],pattern=(i<2?'signature':group)+'-'+n,color=colors[n];const b=document.createElement('button');b.className='variation-choice';const image=document.createElement('img');image.src='assets/pattern-'+pattern+'.webp';image.alt='';const label=document.createElement('span');label.textContent=(i<2?signaturePatterns[n]:patterns[group][n])+' · '+materials[texture];b.append(image,label);b.addEventListener('click',()=>onChange({pattern,texture,color}));results.append(b);}const note=document.createElement('p');note.textContent='Três combinações prontas. Suas fotos e palavras continuam com você.';results.append(note);});
 return {render};
}
